import { Schema } from "effect";
import {
  HttpApiEndpoint,
  HttpApiError,
  HttpApiGroup,
  HttpApiSchema,
  OpenApi,
} from "effect/unstable/httpapi";

const AgentMessageText = Schema.String.check(
  Schema.isLengthBetween(1, 4_000),
).annotate({
  identifier: "AgentMessageText",
  title: "Agent message",
  description: "A user message sent to the agent.",
});

const AgentReferenceLabel = Schema.String.check(Schema.isLengthBetween(1, 500));
export const AGENT_REFERENCE_LIMIT = 20;

export type AgentReference<Resource> = {
  readonly label: string;
  readonly resource: Resource;
};

export const makeAgentReference = <const Resource extends Schema.Top>(
  resource: Resource,
) =>
  Schema.Struct({
    label: AgentReferenceLabel,
    resource,
  }).annotate({
    identifier: "AgentReference",
    title: "Agent reference",
    description: "A resource referenced by an agent message.",
  });

export type AgentAction<Resource = never> =
  | {
      readonly type: "message";
      readonly text: string;
      readonly references?: ReadonlyArray<AgentReference<Resource>>;
    }
  | {
      readonly type: "approval";
      readonly approvalId: string;
      readonly approved: boolean;
    };

const makeAgentAction = <const Resource extends Schema.Top>(
  resource: Resource,
) =>
  Schema.Union([
    Schema.Struct({
      type: Schema.Literal("message"),
      text: AgentMessageText,
      references: Schema.optional(
        Schema.Array(makeAgentReference(resource)).check(
          Schema.isMaxLength(AGENT_REFERENCE_LIMIT),
        ),
      ),
    }),
    Schema.Struct({
      type: Schema.Literal("approval"),
      approvalId: Schema.NonEmptyString,
      approved: Schema.Boolean,
    }),
  ]).annotate({
    identifier: "AgentAction",
    title: "Agent action",
    description:
      "A message with optional references or a tool approval response.",
  });

export const AgentToolMetadata = Schema.Struct({
  title: Schema.optional(Schema.String),
  description: Schema.optional(Schema.String),
  destructive: Schema.Boolean,
}).annotate({ identifier: "AgentToolMetadata" });

export const AgentEvent = Schema.Union([
  Schema.Struct({
    type: Schema.Literal("message-start"),
    messageId: Schema.String,
  }),
  Schema.Struct({
    type: Schema.Literal("text-delta"),
    messageId: Schema.String,
    delta: Schema.String,
  }),
  Schema.Struct({
    type: Schema.Literal("tool-call"),
    messageId: Schema.String,
    toolCallId: Schema.String,
    name: Schema.String,
    input: Schema.Unknown,
    metadata: AgentToolMetadata,
  }),
  Schema.Struct({
    type: Schema.Literal("tool-result"),
    toolCallId: Schema.String,
    name: Schema.String,
    isFailure: Schema.Boolean,
  }),
  Schema.Struct({
    type: Schema.Literal("approval-required"),
    approvalId: Schema.String,
    toolCallId: Schema.String,
  }),
  Schema.Struct({
    type: Schema.Literal("history"),
    value: Schema.String,
  }),
  Schema.Struct({ type: Schema.Literal("finish") }),
  Schema.Struct({
    type: Schema.Literal("error"),
    code: Schema.Literals([
      "unavailable",
      "invalid-request",
      "round-limit",
      "stream-failed",
    ]),
  }),
]).annotate({
  identifier: "AgentEvent",
  title: "Agent stream event",
  description: "An event emitted by the agent endpoint.",
});

export type AgentEvent = typeof AgentEvent.Type;
export type AgentErrorCode = Extract<
  AgentEvent,
  { readonly type: "error" }
>["code"];

const AgentStreamError = Schema.Struct({
  code: Schema.Literals(["unavailable", "stream-failed"]),
}).annotate({
  identifier: "AgentStreamError",
  title: "Agent stream error",
  description: "A recoverable agent stream failure.",
});

export type AgentRequest<Resource> = {
  readonly action: AgentAction<Resource>;
  readonly context?: AgentReference<Resource>;
  readonly history?: string;
};

export const makeAgentApiGroup = <const Resource extends Schema.Top>(
  resource: Resource,
) => {
  const AgentAction = makeAgentAction(resource);
  const AgentRequest = Schema.Struct({
    action: AgentAction,
    context: Schema.optional(makeAgentReference(resource)),
    history: Schema.optional(Schema.String.check(Schema.isMaxLength(500_000))),
  }).annotate({
    identifier: "AgentRequest",
    title: "Agent request",
    description: "An authenticated agent request.",
  });

  return HttpApiGroup.make("agent").add(
    HttpApiEndpoint.post("stream", "/agent", {
      payload: AgentRequest,
      success: HttpApiSchema.StreamSse({
        data: AgentEvent,
        error: AgentStreamError,
      }),
      error: [
        HttpApiError.BadRequest,
        HttpApiError.Unauthorized,
        HttpApiError.Forbidden,
        HttpApiError.InternalServerError,
      ],
    }).annotateMerge(
      OpenApi.annotations({
        summary: "Stream agent",
        description: "Streams an AI agent response for the current session.",
      }),
    ),
  );
};

import { Context, Data, Effect, Layer, Option, Ref, Stream } from "effect";
import {
  Chat,
  LanguageModel,
  Prompt,
  type Response,
  Tool,
  Toolkit,
} from "effect/unstable/ai";

import type { AgentAction, AgentEvent } from "./schema";

export type AgentStreamOptions<Tools extends Record<string, Tool.Any>> = {
  readonly action: AgentAction;
  readonly history?: string;
  readonly systemPrompt: string;
  readonly toolkit: Toolkit.WithHandler<Tools>;
};

class AgentHistoryError extends Data.TaggedError("AgentHistoryError") {}

export class AgentService extends Context.Service<AgentService>()(
  "AgentService",
  {
    make: Effect.gen(function* () {
      const streamErrorDetails = (error: unknown) => {
        if (!error || typeof error !== "object") {
          return { error: String(error) };
        }

        const message = Reflect.get(error, "message");
        const reason = Reflect.get(error, "reason");
        const status = Reflect.get(error, "status");
        const tag = Reflect.get(error, "_tag");

        return {
          ...(typeof message === "string" ? { message } : {}),
          ...(typeof reason === "string" ? { reason } : {}),
          ...(typeof status === "number" ? { status } : {}),
          ...(typeof tag === "string" ? { tag } : {}),
        };
      };

      const eventsForPart = ({
        messageId,
        part,
        toolkit,
      }: {
        readonly messageId: string;
        readonly part: Response.AnyPart;
        readonly toolkit: { readonly tools: Record<string, Tool.Any> };
      }): ReadonlyArray<AgentEvent> => {
        switch (part.type) {
          case "text-delta":
            return [{ type: "text-delta", messageId, delta: part.delta }];
          case "tool-call": {
            const tool = toolkit.tools[part.name];
            const title = tool
              ? Option.getOrUndefined(
                  Context.getOption(tool.annotations, Tool.Title),
                )
              : undefined;
            return [
              {
                type: "tool-call",
                messageId,
                toolCallId: part.id,
                name: part.name,
                input: part.params,
                metadata: {
                  ...(title ? { title } : {}),
                  ...(tool?.description
                    ? { description: tool.description }
                    : {}),
                  destructive: tool
                    ? Context.get(tool.annotations, Tool.Destructive)
                    : false,
                },
              },
            ];
          }
          case "tool-result":
            return [
              {
                type: "tool-result",
                toolCallId: part.id,
                name: part.name,
                isFailure: part.isFailure,
              },
            ];
          case "tool-approval-request":
            return [
              {
                type: "approval-required",
                approvalId: part.approvalId,
                toolCallId: part.toolCallId,
              },
            ];
          case "error":
            return [{ type: "error", code: "stream-failed" }];
          default:
            return [];
        }
      };

      const agentRounds = <Tools extends Record<string, Tool.Any>>({
        conversation,
        messageId,
        prompt,
        round,
        toolkit,
      }: {
        readonly conversation: Chat.Service;
        readonly messageId: string;
        readonly prompt: Prompt.RawInput;
        readonly round: number;
        readonly toolkit: Toolkit.WithHandler<Tools>;
      }): Stream.Stream<
        AgentEvent,
        unknown,
        | LanguageModel.LanguageModel
        | Tool.HandlerServices<Tools[keyof Tools]>
        | Tool.ResultDecodingServices<Tools[keyof Tools]>
      > =>
        Stream.suspend(() => {
          let hasApproval = false;
          const toolCallIds = new Set<string>();
          const toolResultIds = new Set<string>();

          const current = conversation.streamText({ prompt, toolkit }).pipe(
            Stream.tap((part) =>
              Effect.sync(() => {
                if (
                  part.type === "tool-call" &&
                  part.providerExecuted !== true
                ) {
                  toolCallIds.add(part.id);
                }
                if (
                  part.type === "tool-result" &&
                  part.providerExecuted !== true &&
                  part.preliminary !== true
                ) {
                  toolResultIds.add(part.id);
                }
                if (part.type === "tool-approval-request") hasApproval = true;
              }),
            ),
            Stream.tap((part) =>
              part.type === "error"
                ? Effect.logError(
                    "Agent model response failed",
                    streamErrorDetails(part.error),
                  )
                : Effect.void,
            ),
            Stream.flatMap((part) =>
              Stream.fromIterable(eventsForPart({ messageId, part, toolkit })),
            ),
          );

          const continuation = Stream.suspend(() => {
            if (hasApproval || toolCallIds.size === 0) return Stream.empty;
            if (![...toolCallIds].every((id) => toolResultIds.has(id))) {
              return Stream.succeed<AgentEvent>({
                type: "error",
                code: "stream-failed",
              });
            }
            if (round >= 5) {
              return Stream.succeed<AgentEvent>({
                type: "error",
                code: "round-limit",
              });
            }

            return agentRounds({
              conversation,
              messageId,
              prompt: [],
              round: round + 1,
              toolkit,
            });
          });

          return Stream.concat(current, continuation);
        });

      const appendApproval = Effect.fn("AgentService.appendApproval")(
        function* (
          conversation: Chat.Service,
          action: Extract<AgentAction, { readonly type: "approval" }>,
        ) {
          const history = yield* Ref.get(conversation.history);
          let pendingToolCallId: string | undefined;
          const respondedApprovalIds = new Set<string>();
          const resolvedToolCallIds = new Set<string>();

          for (const message of history.content) {
            for (const part of message.content) {
              if (typeof part === "string") continue;
              if (
                part.type === "tool-approval-request" &&
                part.approvalId === action.approvalId
              ) {
                pendingToolCallId = part.toolCallId;
              }
              if (part.type === "tool-approval-response") {
                respondedApprovalIds.add(part.approvalId);
              }
              if (part.type === "tool-result") {
                resolvedToolCallIds.add(part.id);
              }
            }
          }

          if (
            !pendingToolCallId ||
            respondedApprovalIds.has(action.approvalId) ||
            resolvedToolCallIds.has(pendingToolCallId)
          ) {
            return yield* new AgentHistoryError();
          }

          yield* Ref.set(
            conversation.history,
            Prompt.concat(history, [
              Prompt.toolMessage({
                content: [
                  Prompt.toolApprovalResponsePart({
                    approvalId: action.approvalId,
                    approved: action.approved,
                  }),
                ],
              }),
            ]),
          );
        },
      );

      const stream = Effect.fn("AgentService.stream")(function* <
        Tools extends Record<string, Tool.Any>,
      >({ action, history, systemPrompt, toolkit }: AgentStreamOptions<Tools>) {
        const model = yield* LanguageModel.LanguageModel;
        const messageId = crypto.randomUUID();
        const conversation = history
          ? yield* Chat.fromJson(history)
          : yield* Chat.fromPrompt([{ role: "system", content: systemPrompt }]);

        yield* Ref.update(conversation.history, Prompt.setSystem(systemPrompt));

        if (action.type === "approval") {
          yield* appendApproval(conversation, action);
        }

        const rounds = agentRounds({
          conversation,
          messageId,
          prompt: action.type === "message" ? action.text : [],
          round: 1,
          toolkit,
        });
        const complete = Stream.fromEffect(
          Effect.gen(function* () {
            const history = yield* conversation.exportJson;
            return { type: "history", value: history } satisfies AgentEvent;
          }),
        ).pipe(Stream.concat(Stream.succeed<AgentEvent>({ type: "finish" })));
        const response = Stream.concat(rounds, complete).pipe(
          Stream.provideService(LanguageModel.LanguageModel, model),
          Stream.catch((error) =>
            Stream.fromEffect(
              Effect.logError("Agent stream failed", streamErrorDetails(error)),
            ).pipe(
              Stream.drain,
              Stream.concat(
                Stream.make(
                  {
                    type: "error",
                    code: "stream-failed",
                  } satisfies AgentEvent,
                  { type: "finish" } satisfies AgentEvent,
                ),
              ),
            ),
          ),
        );

        return Stream.concat(
          Stream.succeed<AgentEvent>({ type: "message-start", messageId }),
          response,
        );
      });

      return { stream };
    }),
  },
) {
  static readonly layer = Layer.effect(this, this.make);
}

import { Effect, Stream } from "effect";
import { Atom } from "effect/unstable/reactivity";

import type {
  AgentAction,
  AgentErrorCode,
  AgentEvent,
  AgentReference,
  AgentRequest,
} from "../schema";

export type AgentToolStatus =
  | "running"
  | "approval-required"
  | "approved"
  | "denied"
  | "completed"
  | "failed";

export type AgentToolActivity = Extract<
  AgentEvent,
  { readonly type: "tool-call" }
> & {
  readonly approvalId?: string;
  readonly status: AgentToolStatus;
};

export type AgentMessage = {
  readonly id: string;
  readonly role: "user" | "assistant";
  readonly text: string;
  readonly tools: ReadonlyArray<AgentToolActivity>;
};

export type AgentSubmitAction<Resource = never> =
  | {
      readonly type: "message";
      readonly text: string;
      readonly references?: ReadonlyArray<AgentReference<Resource>>;
    }
  | {
      readonly type: "approval";
      readonly approvalId: string;
      readonly toolCallId: string;
      readonly approved: boolean;
    };

export type AgentState = {
  readonly messages: ReadonlyArray<AgentMessage>;
  readonly history?: string;
  readonly pending: boolean;
  readonly error?: AgentErrorCode;
};

export const initialAgentState: AgentState = {
  messages: [],
  pending: false,
};

const updateTool = (
  messages: ReadonlyArray<AgentMessage>,
  toolCallId: string,
  update: (tool: AgentToolActivity) => AgentToolActivity,
) =>
  messages.map((message) => ({
    ...message,
    tools: message.tools.map((tool) =>
      tool.toolCallId === toolCallId ? update(tool) : tool,
    ),
  }));

const failAgentState = (
  state: AgentState,
  error: AgentErrorCode,
): AgentState => {
  const lastMessage = state.messages.at(-1);
  const messages =
    lastMessage?.role === "assistant" &&
    !lastMessage.text &&
    lastMessage.tools.length === 0
      ? state.messages.slice(0, -1)
      : state.messages;
  return { ...state, messages, error };
};

export const reduceAgentEvent = (
  state: AgentState,
  event: AgentEvent,
): AgentState => {
  switch (event.type) {
    case "message-start":
      return {
        ...state,
        messages: [
          ...state.messages,
          { id: event.messageId, role: "assistant", text: "", tools: [] },
        ],
      };
    case "tool-call":
      return {
        ...state,
        messages: state.messages.map((message) =>
          message.id === event.messageId
            ? {
                ...message,
                tools: [...message.tools, { ...event, status: "running" }],
              }
            : message,
        ),
      };
    case "tool-result":
      return {
        ...state,
        messages: updateTool(state.messages, event.toolCallId, (tool) => ({
          ...tool,
          status: event.isFailure ? "failed" : "completed",
        })),
      };
    case "approval-required":
      return {
        ...state,
        messages: updateTool(state.messages, event.toolCallId, (tool) => ({
          ...tool,
          approvalId: event.approvalId,
          status: "approval-required",
        })),
      };
    case "text-delta":
      return {
        ...state,
        messages: state.messages.map((message) =>
          message.id === event.messageId
            ? { ...message, text: message.text + event.delta }
            : message,
        ),
      };
    case "history":
      return { ...state, history: event.value };
    case "error":
      return failAgentState(state, event.code);
    case "finish":
      return state;
  }
};

const defaultErrorCode = (error: unknown): AgentErrorCode => {
  if (error && typeof error === "object") {
    const code = Reflect.get(error, "code");
    if (code === "stream-failed" || code === "unavailable") return code;
  }
  return "unavailable";
};

export type AgentAtomsConfig<Resource> = {
  readonly stream: (
    get: Atom.FnContext,
    request: AgentRequest<Resource>,
  ) => Effect.Effect<Stream.Stream<AgentEvent, unknown>, unknown>;
  readonly errorCode?: (error: unknown) => AgentErrorCode;
};

export type AgentSubmitInput<Resource> = {
  readonly action: AgentSubmitAction<Resource>;
  readonly context?: AgentReference<Resource>;
  readonly scope: string;
};

export const makeAgentAtoms = <Resource>({
  errorCode = defaultErrorCode,
  stream,
}: AgentAtomsConfig<Resource>) => {
  const state = Atom.family((_scope: string) =>
    Atom.make<AgentState>(initialAgentState),
  );

  const submit = Atom.fn<AgentSubmitInput<Resource>>()((input, get) => {
    const submitAction = input.action;
    const stateAtom = state(input.scope);
    const current = get(stateAtom);
    const approvalStatus: AgentToolStatus | undefined =
      submitAction.type === "approval"
        ? submitAction.approved
          ? "approved"
          : "denied"
        : undefined;
    const messages =
      submitAction.type === "message"
        ? [
            ...current.messages,
            {
              id: crypto.randomUUID(),
              role: "user" as const,
              text: submitAction.text,
              tools: [],
            },
          ]
        : current.messages.map((message) => ({
            ...message,
            tools: message.tools.map((tool) =>
              tool.toolCallId === submitAction.toolCallId
                ? { ...tool, status: approvalStatus ?? tool.status }
                : tool,
            ),
          }));

    get.set(stateAtom, {
      ...current,
      messages,
      pending: true,
      error: undefined,
    });

    const action: AgentAction<Resource> =
      submitAction.type === "message"
        ? submitAction
        : {
            type: submitAction.type,
            approvalId: submitAction.approvalId,
            approved: submitAction.approved,
          };

    return stream(get, {
      action,
      context: input.context,
      history: current.history,
    }).pipe(
      Effect.flatMap(
        Stream.runForEach((event) =>
          Effect.sync(() =>
            get.set(stateAtom, reduceAgentEvent(get(stateAtom), event)),
          ),
        ),
      ),
      Effect.catch((error) =>
        Effect.sync(() =>
          get.set(stateAtom, failAgentState(get(stateAtom), errorCode(error))),
        ),
      ),
      Effect.ensuring(
        Effect.sync(() =>
          get.set(stateAtom, { ...get(stateAtom), pending: false }),
        ),
      ),
    );
  });

  const reset = Atom.fnSync<string>()((scope, get) => {
    get.set(state(scope), initialAgentState);
  });

  return { reset, state, submit } as const;
};

